{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.qwe4559999/scopus-mcp",
  "version": "0.1.8",
  "description": "A Model Context Protocol server for the Elsevier Scopus API",
  "repository": {
    "url": "https://github.com/qwe4559999/scopus-mcp",
    "source": "github"
  },
  "license": "MIT",
  "keywords": [
    "scopus",
    "elsevier",
    "academic",
    "research",
    "search",
    "mcp"
  ],
  "packages": [
    {
      "registryType": "pypi",
      "registryBaseUrl": "https://pypi.org",
      "identifier": "scopus-mcp",
      "version": "0.1.8",
      "runtimeHint": "uvx",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
            "name": "SCOPUS_API_KEY",
            "description": "Your Elsevier Scopus API Key",
            "isRequired": true,
            "isSecret": true
        }
      ]
    }
  ]
}
